export const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

export const fmtLat = (v: number) => `${Math.abs(v).toFixed(1)}°${v >= 0 ? "N" : "S"}`;
export const fmtLon = (v: number) => `${Math.abs(v).toFixed(1)}°${v >= 0 ? "E" : "W"}`;
export const fmtInt = (n: number) => Math.round(n).toLocaleString("en-US");
export function fmtCompact(n: number): string {
  const a = Math.abs(n);
  if (a >= 1e9) return (n / 1e9).toFixed(2) + "B";
  if (a >= 1e6) return (n / 1e6).toFixed(2) + "M";
  if (a >= 1e4) return (n / 1e3).toFixed(0) + "k";
  if (a >= 1e3) return (n / 1e3).toFixed(1) + "k";
  return String(Math.round(n));
}
/** Value with one decimal under 10 (converted totals are not integers). */
export const fmtVal = (n: number) => (n !== 0 && Math.abs(n) < 1 ? String(Number(n.toPrecision(2))) : Math.abs(n) < 10 && n % 1 ? n.toFixed(1) : fmtInt(n));

export const rectRing = (b: [number, number, number, number]): Ring => {
  const [la0, la1, lo0, lo1] = b;
  return [[lo0, la0], [lo1, la0], [lo1, la1], [lo0, la1], [lo0, la0]];
};
export function regionFromRing(ring: Ring): RegionDef {
  const lons = ring.map((p) => p[0]), lats = ring.map((p) => p[1]);
  const bbox: [number, number, number, number] = [Math.min(...lats), Math.max(...lats), Math.min(...lons), Math.max(...lons)];
  return { id: `zone:${bbox.map((v) => v.toFixed(2)).join(",")}`, name: "Custom Selection", bbox };
}

