export const TAILLE_RES: Record<number, string> = { 3: "~110 km", 4: "~42 km", 5: "~17 km" };
export const AIRE = new Map<string, number>();
export const aireKm2 = (h: string) => { let a = AIRE.get(h); if (a === undefined) AIRE.set(h, (a = cellArea(h, "km2"))); return a; };

/** Check if [lon, lat] is inside [west, south, east, north] expanded by `margin` fraction on each side. */
export function inViewport(lon: number, lat: number, [w, s, e, n]: [number, number, number, number], margin: number): boolean {
  const lngSpan = w <= e ? e - w : e + 360 - w;
  const latSpan = n - s;
  const dlng = lngSpan * margin, dlat = latSpan * margin;
  if (lat < Math.max(s - dlat, -90) || lat > Math.min(n + dlat, 90)) return false;
  const w2 = w - dlng, e2 = e + dlng;
  if (w <= e) return lon >= w2 && lon <= e2;
  return lon >= w2 || lon <= e2; // antimeridian wrap
}

