/* ── Gall-Peters, emulated on MapLibre's Mercator ──
 * MapLibre only knows Mercator and the globe. Gall-Peters (cylindrical equal-area, standard parallels 45°)
 * keeps x linear in longitude like Mercator and only changes y, so it is drawn as a Mercator map of
 * "warped" latitudes: x = λ, y_merc = 2·sin φ (Gall-Peters scaled by √2 to keep Mercator's x). Every
 * coordinate pushed to the map goes through gpVersCarte, every coordinate read back through gpDeCarte,
 * and the raster tiles are resampled row by row by the "gp://" protocol below. */
export type Projection2D = "gall" | "mercator";
export const RAD = Math.PI / 180;
/** Real latitude -> latitude drawn on the Mercator map (the poles land at ±74.8°). */
export const gpVersCarte = (lat: number) => (2 * Math.atan(Math.exp(2 * Math.sin(lat * RAD))) - Math.PI / 2) / RAD;
/** Latitude read on the Mercator map -> real latitude (beyond ±74.8° it is clamped to the poles). */
export const gpDeCarte = (lat: number) => Math.asin(clamp(Math.log(Math.tan(Math.PI / 4 + clamp(lat, -89.9, 89.9) * RAD / 2)) / 2, -1, 1)) / RAD;
/** Same GeoJSON with every latitude warped (Point, LineString, Polygon and their Multi variants). */
export function gpGeoJSON(fc: unknown): unknown {
  const f = fc as { features?: { geometry?: { type: string; coordinates: unknown } }[] };
  if (!f?.features?.length) return fc;
  const map = (c: unknown): unknown => typeof (c as number[])[0] === "number"
    ? [(c as number[])[0], gpVersCarte((c as number[])[1]), ...(c as number[]).slice(2)]
    : (c as unknown[]).map(map);
  return { ...f, features: f.features.map((ft) => ft.geometry ? { ...ft, geometry: { ...ft.geometry, coordinates: map(ft.geometry.coordinates) } } : ft) };
}
export const ESRI_TPL: Record<string, string> = {
  sat: `${ESRI}/World_Imagery/MapServer/tile/{z}/{y}/{x}`,
  roads: `${ESRI}/Reference/World_Transportation/MapServer/tile/{z}/{y}/{x}`,
  places: `${ESRI}/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}`,
};
/** Tile URLs of a raster source, real Mercator or resampled to Gall-Peters. */
export const tuilesPour = (id: string, gp: boolean) => [gp ? `gp://${id}/{z}/{x}/{y}` : ESRI_TPL[id]];
/** Style for the first render, with the tiles of the projection the page opens on. */
export const styleInitial = (gp: boolean): StyleSpecification => ({
  ...SAT_STYLE,
  sources: Object.fromEntries(Object.entries(SAT_STYLE.sources).map(([id, s]) => [id, { ...s, tiles: tuilesPour(id, gp) }])) as StyleSpecification["sources"],
});
export const T = 256;
/** World pixel row (Mercator, zoom z) -> latitude, and back. */
export const rowVersLat = (y: number, z: number) => Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / (T * 2 ** z)))) / RAD;
export const latVersRow = (lat: number, z: number) => (1 - Math.log(Math.tan(Math.PI / 4 + lat * RAD / 2)) / Math.PI) / 2 * T * 2 ** z;
export const LAT_MAX = 85.0511;
/** "gp://<source>/{z}/{x}/{y}": builds a Gall-Peters tile from the Esri Mercator tiles. The column (longitude)
 * is unchanged, each output row is copied from the real-latitude row of a source tile. Zoom z+1 sources give
 * full vertical detail at the equator (Gall-Peters stretches it ×2); near the poles, where it squeezes, the
 * source zoom drops so a tile never needs more than a handful of source rows. */
export async function tuileGallPeters(url: string, signal: AbortSignal): Promise<ImageBitmap> {
  const [, id, zs, xs, ys] = url.match(/^gp:\/\/(\w+)\/(\d+)\/(\d+)\/(\d+)/) ?? [];
  const z = Number(zs), x = Number(xs), y = Number(ys);
  const tpl = ESRI_TPL[id];
  // real latitude of each output row (NaN beyond the poles or the Mercator source limit)
  const lats = Array.from({ length: T }, (_, r) => {
    const lm = rowVersLat(y * T + r + 0.5, z);
    const l = Math.log(Math.tan(Math.PI / 4 + lm * RAD / 2)) / 2;
    return Math.abs(l) > 1 ? NaN : Math.asin(l) / RAD;
  }).map((l) => (Math.abs(l) > LAT_MAX ? NaN : l));
  const ok = lats.filter((l) => !Number.isNaN(l));
  const canvas = new OffscreenCanvas(T, T);
  const ctx = canvas.getContext("2d")!;
  if (ok.length) {
    let zsrc = Math.min(z + 1, 19);
    const span = (zz: number) => Math.floor(latVersRow(Math.min(...ok), zz) / T) - Math.floor(latVersRow(Math.max(...ok), zz) / T) + 1;
    while (zsrc > 0 && span(zsrc) > 4) zsrc--;
    const k = 2 ** (zsrc - z); // source columns per output tile (zsrc may drop below z: then a fraction)
    const sx0 = x * k, nx = Math.max(1, Math.round(k));
    const ty0 = Math.floor(latVersRow(Math.max(...ok), zsrc) / T), ty1 = Math.floor(latVersRow(Math.min(...ok), zsrc) / T);
    const tuiles = new Map<string, ImageBitmap>();
    await Promise.all(Array.from({ length: (ty1 - ty0 + 1) * nx }, async (_, i) => {
      const tx = Math.floor(sx0) + (i % nx), ty = ty0 + Math.floor(i / nx);
      const r = await fetch(tpl.replace("{z}", String(zsrc)).replace("{x}", String(tx)).replace("{y}", String(ty)), { signal });
      if (r.ok) tuiles.set(`${tx}/${ty}`, await createImageBitmap(await r.blob()));
    }));
    lats.forEach((l, r) => {
      if (Number.isNaN(l)) return;
      const yr = latVersRow(l, zsrc), ty = Math.floor(yr / T), sy = Math.min(T - 1, Math.floor(yr - ty * T));
      if (k >= 1) {
        for (let c = 0; c < nx; c++) {
          const b = tuiles.get(`${sx0 + c}/${ty}`);
          if (b) ctx.drawImage(b, 0, sy, T, 1, (c * T) / nx, r, T / nx, 1);
        }
      } else { // the output tile is a sub-part of one source tile
        const b = tuiles.get(`${Math.floor(sx0)}/${ty}`);
        if (b) ctx.drawImage(b, (sx0 - Math.floor(sx0)) * T, sy, k * T, 1, 0, r, T, 1);
      }
    });
    tuiles.forEach((b) => b.close());
  }
  return canvas.transferToImageBitmap(); // MapLibre takes an ImageBitmap from addProtocol as is
}

export function niceTicks(max: number, n = 3): number[] {
  if (max <= 0) return [0, 1];
  const raw = max / n;
  const p = Math.pow(10, Math.floor(Math.log10(raw)));
  const f = raw / p;
  const step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;
  const out: number[] = [];
  for (let v = 0; v <= max + step * 0.999; v += step) out.push(v);
  return out;
}
export function Seg<T extends string>(props: { label: string; value: T; options: { v: T; t: string }[]; onChange: (v: T) => void }) {
  return (
    <div className="hd-seg" role="radiogroup" aria-label={props.label}>
      {props.options.map((o) => (
        <button key={o.v} role="radio" aria-checked={props.value === o.v} className={props.value === o.v ? "on" : ""} onClick={() => props.onChange(o.v)}>
          {o.t}
        </button>
      ))}
    </div>
  );
}

export const bboxToSizeKm = (bbox: [number, number, number, number]) =>
  Math.round((bbox[1] - bbox[0]) * 111.32 * 10) / 10;

export type CoordErr = { latMax: string; lonMax: string; sizeKm: string };
/** Square box whose north-east corner is (lat max, lon max), `size` km a side; errors per field when invalid. */
export function bboxFromCorner(latMax: string, lonMax: string, sizeKm: string): { err: CoordErr; bbox: [number, number, number, number] | null } {
  const lat1 = parseFloat(latMax), lon1 = parseFloat(lonMax), sz = parseFloat(sizeKm);
  const err: CoordErr = { latMax: "", lonMax: "", sizeKm: "" };
  if (isNaN(lat1) || lat1 < -90 || lat1 > 90) err.latMax = "Must be −90 to 90";
  if (isNaN(lon1) || lon1 < -180 || lon1 > 180) err.lonMax = "Must be −180 to 180";
  if (isNaN(sz) || sz <= 0 || sz > 20000) err.sizeKm = "Must be 1–20 000";
  if (err.latMax || err.lonMax || err.sizeKm) return { err, bbox: null };
  const latSpan = sz / 111.32;
  const lonSpan = sz / (111.32 * Math.cos(lat1 * Math.PI / 180));
  return { err, bbox: [Math.max(-90, lat1 - latSpan), lat1, lon1 - lonSpan, lon1] };
}

/** Lon max / Lat max / Size (km) inputs, shared by the region card and the search panel. */
export function CoordFields({ idPrefix, latMax, lonMax, sizeKm, setLatMax, setLonMax, setSizeKm, err, onEnter }: {
  idPrefix: string; latMax: string; lonMax: string; sizeKm: string;
  setLatMax: (v: string) => void; setLonMax: (v: string) => void; setSizeKm: (v: string) => void;
  err: CoordErr; onEnter: () => void;
}) {
  return (
    <div className="hd-rc-grid3">
      {([
        { id: "lonMax", label: "Lon max", val: lonMax, onChange: setLonMax, err: err.lonMax, step: "0.01" },
        { id: "latMax", label: "Lat max", val: latMax, onChange: setLatMax, err: err.latMax, step: "0.01" },
        { id: "sizeKm", label: "Size (km)", val: sizeKm, onChange: setSizeKm, err: err.sizeKm, step: "1" },
      ] as Array<{ id: string; label: string; val: string; onChange: (v: string) => void; err: string; step: string }>).map(({ id, label, val, onChange, err, step }) => (
        <div key={id} className="hd-rc-field">
          <label htmlFor={`${idPrefix}-${id}`} className="hd-rc-fieldlabel">{label}</label>
          <input
            id={`${idPrefix}-${id}`}
            type="number"
            step={step}
            className={"hd-rc-fieldinput" + (err ? " err" : "")}
            value={val}
            aria-describedby={err ? `${idPrefix}-${id}-err` : undefined}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && onEnter()}
          />
          {err && <span id={`${idPrefix}-${id}-err`} role="alert" className="hd-rc-fielderr">{err}</span>}
        </div>
      ))}
    </div>
  );
}

/** Region name with its Rename button, shown once in the panel header. */
export function RegionName({ name, onRename }: { name: string; onRename: (name: string) => void }) {
  /* ── Rename ── */
  const [renaming, setRenaming] = useState(false);
  const [nameInput, setNameInput] = useState(name);
  const nameInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { setNameInput(name); setRenaming(false); }, [name]);
  useEffect(() => { if (renaming) nameInputRef.current?.focus(); }, [renaming]);

  const commitRename = () => {
    const v = nameInput.trim().slice(0, 40);
    if (v) onRename(v); else setNameInput(name);
    setRenaming(false);
  };
  const cancelRename = () => { setNameInput(name); setRenaming(false); };

  return (
    <div className="hd-rc-titlerow">
      {renaming ? (
        <input
          ref={nameInputRef}
          id="hd-rc-nameinput"
          className="hd-rc-nameinput hd-mono"
          value={nameInput}
          maxLength={40}
          aria-label="Region name"
          onChange={(e) => setNameInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") commitRename(); if (e.key === "Escape") cancelRename(); }}
          onBlur={commitRename}
        />
      ) : (
        <span className="hd-mono hd-name">{name}</span>
      )}
      {!renaming && (
        <button
          className="hd-rc-rename"
          aria-label="Rename region"
          onClick={() => { setNameInput(name); setRenaming(true); }}
        >
          <svg width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M9.5 2.5l2 2-7 7H2.5v-2l7-7z" />
          </svg>
          Rename
        </button>
      )}
    </div>
  );
}

